#include "kernel_operator.h"

using namespace AscendC;

constexpr int64_t BUFFER_NUM = 2;

template <typename T>
class IndexPutKernel {
public:
    __aicore__ inline IndexPutKernel() {}

    __aicore__ inline void Init(GM_ADDR self, GM_ADDR index, GM_ADDR values,
                                int64_t selfLength, int64_t indexSize,
                                int64_t formerNum, int64_t formerLength,
                                int64_t tailLength, int64_t tileLength,
                                int64_t accumulate, int64_t dtypeSize);
    __aicore__ inline void Process();

private:
    __aicore__ inline void CopyIn(int64_t offset, int64_t len);
    __aicore__ inline void Compute(int64_t len);
    __aicore__ inline void CopyOut(int64_t len);

private:
    TPipe pipe;

    TQue<QuePosition::VECIN, BUFFER_NUM> inQueueIndex;
    TQue<QuePosition::VECIN, BUFFER_NUM> inQueueValues;
    TQue<QuePosition::VECOUT, BUFFER_NUM> outQueueValues;

    GlobalTensor<T> selfGm;
    GlobalTensor<int32_t> indexGm;
    GlobalTensor<T> valuesGm;

    int64_t selfLength_ = 0;
    int64_t indexSize_ = 0;
    int64_t formerNum_ = 0;
    int64_t formerLength_ = 0;
    int64_t tailLength_ = 0;
    int64_t tileLength_ = 0;
    int64_t accumulate_ = 0;
    int64_t dtypeSize_ = 0;
    int64_t blockOffset_ = 0;
    int64_t blockLength_ = 0;
};

template <typename T>
__aicore__ inline void IndexPutKernel<T>::Init(GM_ADDR self, GM_ADDR index, GM_ADDR values,
                                                int64_t selfLength, int64_t indexSize,
                                                int64_t formerNum, int64_t formerLength,
                                                int64_t tailLength, int64_t tileLength,
                                                int64_t accumulate, int64_t dtypeSize) {
    selfLength_ = selfLength;
    indexSize_ = indexSize;
    formerNum_ = formerNum;
    formerLength_ = formerLength;
    tailLength_ = tailLength;
    tileLength_ = tileLength;
    accumulate_ = accumulate;
    dtypeSize_ = dtypeSize;

    selfGm.SetGlobalBuffer((__gm__ T*)self, selfLength);
    indexGm.SetGlobalBuffer((__gm__ int32_t*)index, indexSize);
    valuesGm.SetGlobalBuffer((__gm__ T*)values, indexSize);

    int64_t indexBufSize = tileLength * sizeof(int32_t);
    int64_t valuesBufSize = tileLength * dtypeSize;

    pipe.InitBuffer(inQueueIndex, BUFFER_NUM, indexBufSize);
    pipe.InitBuffer(inQueueValues, BUFFER_NUM, valuesBufSize);
    pipe.InitBuffer(outQueueValues, BUFFER_NUM, valuesBufSize);

    int64_t blockIdx = GetBlockIdx();
    if (blockIdx < formerNum_) {
        blockOffset_ = blockIdx * formerLength_;
        blockLength_ = formerLength_;
    } else {
        blockOffset_ = formerNum_ * formerLength_ + (blockIdx - formerNum_) * tailLength_;
        blockLength_ = tailLength_;
    }
}

template <typename T>
__aicore__ inline void IndexPutKernel<T>::CopyIn(int64_t offset, int64_t len) {
    LocalTensor<int32_t> indexLocal = inQueueIndex.AllocTensor<int32_t>();
    DataCopyExtParams indexParams;
    indexParams.blockCount = 1;
    indexParams.blockLen = static_cast<uint32_t>(len * sizeof(int32_t));
    indexParams.srcStride = 0;
    indexParams.dstStride = 0;
    DataCopyPadExtParams<int32_t> indexPadParams;
    indexPadParams.isPad = false;
    DataCopyPad(indexLocal, indexGm[offset], indexParams, indexPadParams);
    inQueueIndex.EnQue(indexLocal);

    LocalTensor<T> valuesLocal = inQueueValues.AllocTensor<T>();
    DataCopyExtParams valuesParams;
    valuesParams.blockCount = 1;
    valuesParams.blockLen = static_cast<uint32_t>(len * dtypeSize_);
    valuesParams.srcStride = 0;
    valuesParams.dstStride = 0;
    DataCopyPadExtParams<T> valuesPadParams;
    valuesPadParams.isPad = false;
    DataCopyPad(valuesLocal, valuesGm[offset], valuesParams, valuesPadParams);
    inQueueValues.EnQue(valuesLocal);
}

template <typename T>
__aicore__ inline void IndexPutKernel<T>::Compute(int64_t len) {
    LocalTensor<int32_t> indexLocal = inQueueIndex.DeQue<int32_t>();
    LocalTensor<T> valuesLocal = inQueueValues.DeQue<T>();
    LocalTensor<T> outLocal = outQueueValues.AllocTensor<T>();

    if (accumulate_ != 0) {
        SetAtomicAdd<T>();
        for (int64_t i = 0; i < len; ++i) {
            int32_t idx = indexLocal.GetValue(i);
            T val = valuesLocal.GetValue(i);
            if (idx >= 0 && idx < selfLength_) {
                selfGm.SetValue(idx, val);
            }
        }
        SetAtomicNone();
    } else {
        for (int64_t i = 0; i < len; ++i) {
            int32_t idx = indexLocal.GetValue(i);
            T val = valuesLocal.GetValue(i);
            if (idx >= 0 && idx < selfLength_) {
                selfGm.SetValue(idx, val);
            }
        }
    }

    inQueueIndex.FreeTensor(indexLocal);
    inQueueValues.FreeTensor(valuesLocal);
    outQueueValues.EnQue(outLocal);
}

template <typename T>
__aicore__ inline void IndexPutKernel<T>::CopyOut(int64_t len) {
    LocalTensor<T> outLocal = outQueueValues.DeQue<T>();
    outQueueValues.FreeTensor(outLocal);
}

template <typename T>
__aicore__ inline void IndexPutKernel<T>::Process() {
    int64_t tileNum = (blockLength_ + tileLength_ - 1) / tileLength_;
    int64_t tailTileLength = blockLength_ - (tileNum - 1) * tileLength_;

    for (int64_t i = 0; i < tileNum; ++i) {
        int64_t curTileLength = (i == tileNum - 1) ? tailTileLength : tileLength_;
        if (curTileLength <= 0) break;
        CopyIn(blockOffset_ + i * tileLength_, curTileLength);
        Compute(curTileLength);
        CopyOut(curTileLength);
    }
}

extern "C" __global__ __aicore__ void index_put_kernel(GM_ADDR self, GM_ADDR index, GM_ADDR values,
                                                          int64_t selfLength, int64_t indexSize,
                                                          int64_t formerNum, int64_t formerLength,
                                                          int64_t tailLength, int64_t tileLength,
                                                          int64_t accumulate, int64_t dtypeSize) {
    if (dtypeSize == 4) {
        IndexPutKernel<float> op;
        op.Init(self, index, values, selfLength, indexSize, formerNum, formerLength,
                tailLength, tileLength, accumulate, dtypeSize);
        op.Process();
    } else if (dtypeSize == 2) {
        IndexPutKernel<half> op;
        op.Init(self, index, values, selfLength, indexSize, formerNum, formerLength,
                tailLength, tileLength, accumulate, dtypeSize);
        op.Process();
    }
}
