#include "torch_kernel_helper.h"
#include "aclrtlaunch_index_put_kernel.h"
#include <torch/extension.h>
#include "tiling/platform/platform_ascendc.h"

namespace ascend_kernel {

constexpr int64_t MAX_CORES = 40;

at::Tensor index_put(const at::Tensor &self, const at::Tensor &index,
                     const at::Tensor &values, bool accumulate) {
    // ---- 输入校验 ----
    TORCH_CHECK(self.device().type() == at::DeviceType::PrivateUse1,
                "index_put: self must be on NPU device");
    TORCH_CHECK(index.device().type() == at::DeviceType::PrivateUse1,
                "index_put: index must be on NPU device");
    TORCH_CHECK(values.device().type() == at::DeviceType::PrivateUse1,
                "index_put: values must be on NPU device");

    TORCH_CHECK(self.dim() == 1, "index_put: self must be 1D");
    TORCH_CHECK(index.dim() == 1, "index_put: index must be 1D");
    TORCH_CHECK(values.dim() == 1, "index_put: values must be 1D");
    TORCH_CHECK(index.numel() == values.numel(),
                "index_put: index and values must have same length");

    TORCH_CHECK(self.scalar_type() == at::kFloat ||
                self.scalar_type() == at::kHalf ||
                self.scalar_type() == at::kBFloat16,
                "index_put: only float32, float16 and bfloat16 are supported");

    // ---- 连续化 ----
    at::Tensor selfContiguous = self.contiguous();
    at::Tensor valuesContiguous = values.contiguous();

    // ---- Index 转 int32 ----
    auto indexInt32 = index.contiguous().to(at::kInt);

    // ---- 平台参数 ----
    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
    uint64_t ubSize;
    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);

    // ---- 参数 ----
    int64_t selfLength = selfContiguous.numel();
    int64_t indexSize = indexInt32.numel();
    int64_t dtypeSize = selfContiguous.element_size();

    if (indexSize == 0) {
        return selfContiguous;
    }

    // ---- Block 级 Tiling ----
    int64_t alignNum = 32 / dtypeSize;
    if (alignNum < 1) alignNum = 1;

    int64_t totalLengthCore = (indexSize + coreNum - 1) / coreNum;
    int64_t totalLengthCoreAlign = ((totalLengthCore + alignNum - 1) / alignNum) * alignNum;
    int64_t usedCoreNum = (indexSize + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
    if (usedCoreNum > coreNum) usedCoreNum = coreNum;
    if (usedCoreNum < 1) usedCoreNum = 1;

    int64_t formerNum = usedCoreNum - 1;
    int64_t tailNum = 1;
    int64_t formerLength = totalLengthCoreAlign;
    int64_t tailLength = indexSize - (usedCoreNum - 1) * formerLength;
    if (tailLength < 0) tailLength = 0;

    // ---- UB 级 Tiling ----
    int64_t bufferCoefficient = (dtypeSize == 4) ? 24 : 16;
    int64_t maxTileElements = static_cast<int64_t>(ubSize) / bufferCoefficient;
    int64_t tileLength = (maxTileElements / alignNum) * alignNum;
    if (tileLength < alignNum) tileLength = alignNum;

    // ---- blockDim ----
    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
    if (blockDim < 1) blockDim = 1;

    // ---- 左值参数 ----
    int64_t accumulateFlag = accumulate ? 1 : 0;

    // ---- 启动 kernel ----
    EXEC_KERNEL_CMD(index_put_kernel, blockDim, selfContiguous, indexInt32, valuesContiguous,
                    selfLength, indexSize, formerNum, formerLength,
                    tailLength, tileLength, accumulateFlag, dtypeSize);

    return selfContiguous;
}

}  // namespace ascend_kernel
